// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // Fuzz the 'from' address and the caddress target; the key deciding parameter is the _tos array length = 0
    function testFuzz_property(address from, address caddress) public {
        // Keep addresses wide-open; we will call transfer with an empty _tos array to exercise the difference.
        address[] memory tos = new address[](0);
        uint256[] memory vals = new uint256[](0);

        // Call and observe whether it reverts or not via try/catch.
        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the reference contract always reverts (so ok == false) for empty _tos;
        // the mutant removes the require and will return true (ok == true) for some inputs.
        // Assert that the call reverted (ok == false). This holds for the reference for ALL inputs,
        // and will fail for the mutant when _tos is empty.
        assertTrue(!ok);
    }
}
